/usr/bin/bash -lc "mkdir -p run_trace/filtered_counts
awk 'BEGIN{FS=OFS=\"\\t\"}
  FNR==1 {sample[ARGIND]="'$2; next}
  ARGIND==1 {order[++n]=$1}
  {counts[$1,ARGIND]=$2+0}
  END {
    for (i=1; i<=n; i++) {
      g=order[i]; pass=0;
      for (j=1; j<=4; j++) if ((counts[g,j]+0) >= 10) pass++;
      if (pass >= 2) print g;
    }
  }'"' \\
  data/inputs/counts_from_changed_condition/srr5085169_counts_table/srr5085169_counts_table.dat \\
  data/inputs/counts_from_changed_condition/srr5085170_counts_table/srr5085170_counts_table.dat \\
  data/inputs/counts_from_reference_condition/srr5085167_counts_table/srr5085167_counts_table.dat \\
  data/inputs/counts_from_reference_condition/srr5085168_counts_table/srr5085168_counts_table.dat \\
  > run_trace/retained_gene_ids.txt
for src in \\
  data/inputs/counts_from_changed_condition/srr5085169_counts_table/srr5085169_counts_table.dat \\
  data/inputs/counts_from_changed_condition/srr5085170_counts_table/srr5085170_counts_table.dat \\
  data/inputs/counts_from_reference_condition/srr5085167_counts_table/srr5085167_counts_table.dat \\
  data/inputs/counts_from_reference_condition/srr5085168_counts_table/srr5085168_counts_table.dat; do
  base="'$(basename "$src" .dat)
  awk '"'BEGIN{FS=OFS=\"\\t\"} NR==FNR{keep["'$1]=1; next} FNR==1 || keep[$1]'"' run_trace/retained_gene_ids.txt \""'$src" > "run_trace/filtered_counts/${base}.filtered.tabular"
done
{
  printf '"'%s\\t%s\\n' \"timestamp_utc\" \""'$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf '"'%s\\t%s\\n' \"assigned_history_id\" \"bbd44e69cb8906b54b24bbddc267e704\"
  printf '%s\\t%s\\n' \"filter_rule\" \"retain genes with >=10 raw counts in at least two of four samples\"
  printf '%s\\t%s\\n' \"retained_genes\" \""'$(wc -l < run_trace/retained_gene_ids.txt)"
} > run_trace/execution_log.tsv
wc -l run_trace/retained_gene_ids.txt run_trace/filtered_counts/*.filtered.tabular
sed -n '"'1,5p' run_trace/filtered_counts/srr5085169_counts_table.filtered.tabular"

