/usr/bin/bash -lc "mkdir -p final_answer
perl -F'\\t' -ane '
  chomp;
  next if /"'^'"\\s*"'$/;
  die "Expected 7 columns at $.'"\\n\" unless @F >= 7;
  my ("'$gene,$lfc,$p) = ($F[0], -1 * $F[2], $F[5]);
  die "Nonfinite lfc for $gene'"\\n\" unless "'$lfc =~ /''^[-+]?(('"\\d+(\\.\\d*)?)|(\\.\\d+))([eE][-+]?\\d+)?"'$/;
  die "Invalid p for $gene: $p'"\\n\" unless "'$p =~ /''^[-+]?(('"\\d+(\\.\\d*)?)|(\\.\\d+))([eE][-+]?\\d+)?"'$/ && $p >= 0 && $p <= 1;
  push @rows, [$gene, $lfc, $p];
  END {
    my $n = scalar @rows;
    my @idx = sort { $rows[$a][2] <=> $rows[$b][2] } 0..$#rows;
    my @q;
    my $min = 1;
    for (my $rank=$n; $rank>=1; $rank--) {
      my $i = $idx[$rank-1];
      my $val = $rows[$i][2] * $n / $rank;
      $val = 1 if $val > 1;
      $min = $val if $val < $min;
      $q[$i] = $min;
    }
    print "gene_id'"\\tlog2_fold_change\\tp_value\\tfdr\\n\";
    for my "'$i (0..$#rows) {
      printf "%s'"\\t%.15g\\t%.15g\\t%.15g\\n\", "'$rows[$i][0], $rows[$i][1], $rows[$i][2], $q[$i];
    }
  }
'"' run_trace/deseq2_result.tsv > final_answer/differential_expression.tsv
printf '{\"method\":\"DESeq2\"}\\n' > final_answer/method.json
{
  printf '%s\\t%s\\n' \"galaxy_deseq2_job_id\" \"bbd44e69cb8906b58249c2c8e9a17db8\"
  printf '%s\\t%s\\n' \"galaxy_deseq2_result_dataset_id\" \"f9cad7b01a47213506d32a0e303100ac\"
  printf '%s\\t%s\\n' \"galaxy_reported_contrast\" \"reference vs changed\"
  printf '%s\\t%s\\n' \"final_lfc_direction\" \"changed vs reference (negated Galaxy output log2FC)\"
  printf '%s\\t%s\\n' \"fdr\" \"Benjamini-Hochberg recomputed across retained genes from Galaxy raw p-values\"
} >> run_trace/execution_log.tsv
wc -l final_answer/differential_expression.tsv
sed -n '1,6p' final_answer/differential_expression.tsv
cat final_answer/method.json"

