/usr/bin/bash -lc "perl -F'\\t' -ane '
  chomp;
  if ("'$.==1) { die "bad header'"\\n\" unless "'$_ eq "gene_id'"\\tlog2_fold_change\\tp_value\\tfdr\"; next }
  die \"bad field count at "'$.'"\\n\" unless @F==4;
  "'$seen{$F[0]}++;
  for my $j (1..3) { die "bad numeric at $. col $j: $F[$j]'"\\n\" unless "'$F[$j] =~ /''^[-+]?(('"\\d+(\\.\\d*)?)|(\\.\\d+))([eE][-+]?\\d+)?"'$/; }
  die "bad p at $.'"\\n\" unless "'$F[2] >= 0 && $F[2] <= 1;
  die "bad fdr at $.'"\\n\" unless "'$F[3] >= 0 && $F[3] <= 1;
  END { die "no rows'"\\n\" if "'$. < 2; for my $g (keys %seen) { die "duplicate $g'"\\n\" if "'$seen{$g} != 1 } print ($.-1), " data rows validated'"\\n\"; }
' final_answer/differential_expression.tsv"

